<?php
declare(strict_types=1);
require __DIR__.'/common.php';$u=cloud_user();$d=db();
$q=is_string($_GET['q']??null)?mb_substr(trim($_GET['q']),0,100):'';$genre=is_string($_GET['genre']??null)&&ctype_digit($_GET['genre'])?(int)$_GET['genre']:0;$mine=($_GET['mine']??'')==='1';$like='%'.$q.'%';
$sql='SELECT s.*,m.name AS genre,u.username FROM z6v_film s JOIN z6v_filmtype m ON m.idft=s.idft JOIN z6_users u ON u.id=s.idu WHERE '.video_access_sql().' AND (s.title LIKE ? OR s.director LIKE ?) AND (?=0 OR s.idft=?) AND (?=0 OR s.idu=?) ORDER BY s.datetime DESC,s.idf DESC';
$s=$d->prepare($sql);$flag=$mine?1:0;$s->bind_param('iissiiii',$u['id'],$u['id'],$like,$like,$genre,$genre,$flag,$u['id']);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$genres=$d->query('SELECT * FROM z6v_filmtype ORDER BY idft')->fetch_all(MYSQLI_ASSOC);$own=video_own_playlists($d,(int)$u['id']);
$s=$d->prepare('SELECT s.*,m.name AS genre,w.position_seconds FROM z6v_watch_progress w JOIN z6v_film s ON s.idf=w.idf JOIN z6v_filmtype m ON m.idft=s.idft WHERE w.idu=? AND w.completed=0 AND w.position_seconds>0 AND '.video_access_sql().' ORDER BY w.updated_at DESC,s.idf DESC LIMIT 12');$s->bind_param('iii',$u['id'],$u['id'],$u['id']);$s->execute();$unfinished=$s->get_result()->fetch_all(MYSQLI_ASSOC);$d->close();
head('myNetflix');video_toolbar('films.php');
?>
<form method="get" action="films.php" class="video-filter card card-body mb-4"><div class="row g-3 align-items-end"><div class="col-12 col-md-5"><label class="form-label" for="search-film">Tytuł lub reżyser</label><input class="form-control" id="search-film" name="q" value="<?=h($q)?>" maxlength="100"></div><div class="col-12 col-md-3"><label class="form-label" for="filter-genre">Gatunek</label><select class="form-select" id="filter-genre" name="genre"><option value="0">Wszystkie gatunki</option><?php foreach($genres as $g): ?><option value="<?=$g['idft']?>"<?=$genre===(int)$g['idft']?' selected':''?>><?=h($g['name'])?></option><?php endforeach; ?></select></div><div class="col-12 col-md-2"><div class="form-check mb-2"><input class="form-check-input" type="checkbox" id="my-songs" name="mine" value="1"<?=$mine?' checked':''?>><label class="form-check-label" for="my-songs">Tylko moje</label></div></div><div class="col-12 col-md-2"><button class="btn btn-primary w-100" type="submit">Szukaj</button></div></div></form>
<?php if($unfinished): ?><section class="mb-4" id="continue-watching"><h2 class="h4 mb-3">A może dokończysz?</h2><div class="row g-3"><?php foreach($unfinished as $film): ?><div class="col-12 col-md-6 col-xl-4"><article class="card h-100 video-film"><a class="film-poster" href="film.php?id=<?=$film['idf']?>"><?=video_cover_html((int)$film['idf'],null,$film['coverfilename'],'Okładka '.$film['title'])?><h3 class="film-poster-title"><?=h($film['title'])?></h3></a><div class="card-body"><span class="badge text-bg-secondary"><?=h($film['genre'])?></span><p class="mb-0 mt-2">Kontynuuj od <?=h(video_duration_label((int)$film['position_seconds']))?> / <?=h(video_duration_label($film['duration_seconds']===null?null:(int)$film['duration_seconds']))?></p></div></article></div><?php endforeach; ?></div></section><?php endif; ?>
<h2 class="h4">Wszystkie filmy</h2>
<p class="text-body-secondary"><?=count($rows)?> filmów</p>
<div class="row g-3"><?php foreach($rows as $film): ?><div class="col-12 col-md-6 col-xl-4"><article class="card h-100 video-film"><a class="film-poster" href="film.php?id=<?=$film['idf']?>"><?=video_cover_html((int)$film['idf'],null,$film['coverfilename'],'Okładka '.$film['title'])?><h2 class="film-poster-title"><?=h($film['title'])?></h2></a><div class="card-body"><div class="d-flex justify-content-between gap-2 mb-3"><span class="badge text-bg-secondary"><?=h($film['genre'])?></span><span class="small text-body-secondary" aria-label="Czas trwania"><?=h(video_duration_label($film['duration_seconds']===null?null:(int)$film['duration_seconds']))?></span></div><?php video_add_form($film,$own); ?></div></article></div><?php endforeach; ?></div>
<?php if(!$rows): ?><div class="card card-body text-center py-5"><h2 class="h4">Brak filmów</h2><p class="text-body-secondary">Dodaj film lub wybierz publiczną playlistę.</p><div><a class="btn btn-primary" href="film_select.php">Dodaj film</a></div></div><?php endif; ?>
<?php foot(); ?>
